function getCookie(e){var t=null;if(document.cookie&&""!=document.cookie)for(var o=document.cookie.split(";"),n=0;n<o.length;n++){var a=jQuery.trim(o[n]);if(a.substring(0,e.length+1)==e+"="){t=decodeURIComponent(a.substring(e.length+1));break}}return t}function csrfSafeMethod(e){return/^(GET|HEAD|OPTIONS|TRACE)$/.test(e)}function duplicate(){var e=$("#id_url").attr("data-url");$.ajax({url:e,type:"GET",data:{evidence_id:""},dataType:"json"}).done(function(e){var t=e.duplicate_info.info;show_message(t)}).fail(function(e,t,o){alert(t+":"+o)})}function clear_all(){document.getElementById("id_pdf_name").value="",document.getElementById("id_shori_date").value=""}function PdfList(){document.getElementById("act").value="",$("#searchForm").submit()}function PdfList_org(){function e(e){let t=$(e);$.each(t,function(e,t){let o=$(t).text();"NG"==o&&$(t).css("background-color","red")})}e(".result"),""==SearchForm.pdf_name.value&&SearchForm.shori_date.value}function delete_evidence_list(){document.getElementById("act").value="del",$("#searchForm").submit()}function change_page_size(){let e=document.getElementById("select_page_size").value;document.getElementById("id_page_size").value=e,document.getElementById("act").value="",$("#searchForm").submit()}var csrftoken=getCookie("csrftoken");$.ajaxSetup({beforeSend:function(e,t){csrfSafeMethod(t.type)||this.crossDomain||e.setRequestHeader("X-CSRFToken",csrftoken)}}),$(function(){$("tr[data-href]").on("click",function(e){if($deleteFlg){$deleteFlg=!1;let e=$(this).data("href"),t=e.indexOf("edit_entry");if(0<t){let o=e.substring(t+11,t+31);document.getElementById("ocrdata_id").value=o,$modal.showModal()}else if(t=e.indexOf("ocrdata_edit/entry/"),0<t){let o="ocrdata_edit/entry/".length,n=e.substring(t+o,t+o+20);document.getElementById("ocrdata_id").value=n,$modal.showModal()}}else 0==$(e.target).closest(".prosessing").length?location.href=$(this).data("href"):show_message("処理中です。")}),$("#ev_table").tablesorter({headers:{1:{sorter:!1},2:{sorter:!1}}})}),jQuery(function(e){e(function(){e("#btn_dropdown").click(function(t){t.stopPropagation(),e("#dropdown").toggleClass("show")}),e(document).on("click",function(t){e("#dropdown").hasClass("show")&&e("#dropdown").toggleClass("show")})})});